def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    resp_c_d = 0
    resp_d_d = 0
    resp_c_c = 0
    resp_d_c = 0

    for i in range(n):
        me, op = history[i]
        if op == 'C':
            opp_c += 1
        if i + 1 < n:
            next_op = history[i + 1][1]
            if me == 'D':
                if next_op == 'C':
                    resp_c_d += 1
                else:
                    resp_d_d += 1
            else:
                if next_op == 'C':
                    resp_c_c += 1
                else:
                    resp_d_c += 1

    opp_d = n - opp_c
    last_my, last_opp = history[-1]

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    soft_exploit = False
    if opp_d == 0 and resp_c_d >= 1:
        soft_exploit = True
    elif resp_c_d >= 3 and resp_c_d >= resp_d_d + 1 and opp_c * 3 >= n * 2:
        soft_exploit = True
    elif resp_c_d >= 5 and resp_c_d >= resp_d_d + 2 and opp_c * 2 >= n:
        soft_exploit = True

    anti_exploit = False
    if resp_c_d + resp_d_d >= 2 and resp_c_c + resp_d_c >= 4:
        if resp_c_d >= resp_d_d + 1 and resp_d_c >= resp_c_c + 2:
            anti_exploit = True
    elif resp_c_d >= 1 and resp_d_d == 0 and resp_d_c >= 4 and resp_d_c >= resp_c_c + 3:
        anti_exploit = True

    hostile = False
    if opp_c == 0 and n >= 2:
        hostile = True
    elif n >= 5 and opp_c * 4 < n:
        hostile = True
    elif opp_d_streak >= 6:
        hostile = True
    elif n >= 10 and opp_d_streak >= 4 and opp_c * 3 < n:
        hostile = True

    if anti_exploit:
        return 'D'

    if soft_exploit:
        if last_opp == 'D' and opp_c * 3 >= n * 2 and opp_d_streak <= 6 and n < 96:
            return 'C'
        return 'D'

    if n == 4 and opp_d == 0:
        return 'D'

    if hostile:
        return 'D'

    if last_opp == 'C':
        return 'C'

    if opp_d_streak >= 6:
        return 'D'

    if last_my == 'D':
        if opp_d_streak >= 3 and opp_c * 2 < n:
            return 'D'
        return 'C'

    if n >= 2 and history[-2][0] == 'D':
        if opp_d_streak >= 3 and opp_c * 2 < n:
            return 'D'
        return 'C'

    return 'D'
